from pathlib import Path
import sys
p=Path(sys.argv[1]);p.parent.mkdir(parents=True,exist_ok=True)
with p.open('a',encoding='utf-8',newline='') as o:o.write("ons\", () => {\n+  const directory = join(TEST_HOME, \"format-transition\");\n+  const config = join(TEST_HOME, \"transition-config.toml\");\n+\n+  it(\"removes legacy descriptors on upgrade, and JSON descriptors on downgrade\", async () => {\n+    const install = (codexVersion: string) => installCodexPluginMarketplace(\n+      MOCK_SKILLS, \"26.5.14\", \"no-shell\",\n+      { marketplaceDir: directory, configPath: config, codexVersion }\n+    );\n+    const plugin = join(directory, \"plugins\", \"rrr\");\n+    await install(\"0.128.0\");\n+    expect(existsSync(join(directory, \"manifest.toml\"))).toBe(true);\n+    expect(existsSync(join(plugin, \"plugin.toml\"))).toBe(true);\n+\n+    await install(\"0.130.0\");\n+    expect(existsSync(join(directory, \"manifest.toml\"))).toBe(false);\n+    expect(existsSync(join(plugin, \"plugin.toml\"))).toBe(false);\n+    expect(existsSync(join(plugin, \"prompt.md\"))).toBe(false);\n+    expect(existsSync(join(plugin, \".codex-plugin\", \"plugin.json\"))).toBe(true);\n+\n+    await install(\"0.128.0\");\n+    expect(existsSync(join(plugin, \".codex-plugin\"))).toBe(false);\n+    expect(existsSync(join(plugin, \"skills\"))).toBe(false);\n+    expect(existsSync(join(plugin, \"plugin.toml\"))).toBe(true);\n+  });\n+\n+  it(\"rejects unsafe skill names without writing outside the plugins directory\", async () => {\n+    const outside = join(TEST_HOME, \"escaped-skill\");\n+    await expect(installCodexPluginMarketplace(\n+      [{ ...MOCK_SKILLS[0], name: \"../../escaped-skill\" }],\n+      \"26.5.14\", \"no-shell\",\n+      { marketplaceDir: directory, configPath: config, codexVersion: \"0.130.0\" }\n+    )).rejects.toThrow(\"Invalid Codex plugin skill name\");\n+    expect(existsSync(outside)).toBe(false);\n+  });\n+});\n")
